const produk: { nama: string; harga: number; stok: number } = {
  nama: "Kopi Susu",
  harga: 18000,
  stok: 12,
};
produk.stok -= 2;
const { nama, harga } = produk;
console.log(nama, harga);
console.log("Sisa:", produk.stok);

